#!/usr/bin/env node
/* eslint-disable no-bitwise -- The ZIP format packs DOS timestamps and file attributes into bit fields. */
/**
 * Builds the installable plugin ZIP: dist/merchboard-mvp-<version>.zip.
 *
 * Run via `npm run package`, which builds the dashboard first. The package is
 * an allowlist of runtime files (docs/DEVELOPMENT.md#distributionspakke):
 *
 *   merchboard.php, uninstall.php, src/, templates/, languages/, assets/js/
 *   (tracked in git at HEAD) and build/ (generated by `npm run build`).
 *
 * No vendor/ (the plugin uses its own autoloader, ADR-017), no sources,
 * tests, tooling or configuration. The script refuses to run on a dirty
 * working tree, fails if required runtime files are missing or a forbidden
 * file slips in, writes a deterministic ZIP (sorted entries, fixed timestamp
 * from the HEAD commit, fixed permissions) and validates the result by
 * reading it back.
 *
 * No dependencies: ZIP is written with node:zlib (deflate + crc32).
 *
 * Release builds pass the git tag: `npm run package -- --tag v1.2.3`. The tag
 * must be `v` + the plugin version and point at HEAD, so a release asset can
 * never carry a different version or commit than its tag
 * (docs/DEVELOPMENT.md#release).
 */
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
	existsSync,
	mkdirSync,
	readFileSync,
	readdirSync,
	statSync,
	writeFileSync,
} from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { crc32, deflateRawSync, inflateRawSync } from 'node:zlib';

const ROOT = join( dirname( fileURLToPath( import.meta.url ) ), '..' );
const PLUGIN_DIR = 'merchboard';

/** Tracked runtime paths (files or directories) taken from git at HEAD. */
const TRACKED = [
	'merchboard.php',
	'uninstall.php',
	'src',
	'templates',
	'languages',
	'assets/js',
];

/** Generated runtime directory (gitignored). */
const GENERATED = 'build';

/** Files that must be in every package. */
const REQUIRED = [
	'merchboard.php',
	'uninstall.php',
	'src/Plugin.php',
	'src/Core/Autoloader.php',
	'src/Core/Requirements.php',
	'templates/dashboard/shell.php',
	'templates/dashboard/no-access.php',
	'templates/alerts/overlay.php',
	'assets/js/creator-user-search.js',
	'build/dashboard.js',
	'build/dashboard.css',
	'build/dashboard-rtl.css',
	'build/dashboard.asset.php',
	'build/overlay.js',
	'build/overlay.css',
	'build/overlay.asset.php',
	'build/alerts-admin.js',
	'build/alerts-admin.asset.php',
	'languages/merchboard.pot',
	'languages/merchboard-da_DK.po',
	'languages/merchboard-da_DK.mo',
	// Script translations are looked up by the md5 of the bundle path.
	`languages/merchboard-da_DK-${ createHash( 'md5' ).update( 'build/dashboard.js' ).digest( 'hex' ) }.json`,
];

/** Anything matching these must never be packaged. */
const FORBIDDEN = [
	/(^|\/)node_modules\//,
	/(^|\/)vendor\//,
	/(^|\/)tests?\//,
	/(^|\/)\.git(\/|$)/,
	/(^|\/)\.github\//,
	/(^|\/)\.env(\.|$)/,
	/(^|\/)auth\.json$/,
	/\.(pem|key|p12|sqlite|log|map|ts|tsx|scss|phar)$/,
	/(^|\/)(composer|package)(-lock)?\.json$/,
	/(^|\/)(phpunit|phpcs|phpstan)[^/]*$/,
	/(^|\/)(tsconfig|jest\.config|eslint\.config)[^/]*$/,
	/^assets\/src\//,
	/(^|\/)(\.DS_Store|Thumbs\.db|desktop\.ini)$/,
];

function fail( message ) {
	console.error( `package: ${ message }` );
	process.exit( 1 );
}

function git( ...args ) {
	return execFileSync( 'git', args, { cwd: ROOT, encoding: 'utf8' } ).trim();
}

/** SemVer 2.0 without build metadata, e.g. 1.2.3 or 1.2.3-rc.1. */
const SEMVER =
	/^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(-(0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(\.(0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*)?$/;

/**
 * The plugin version. The plugin header, MERCHBOARD_VERSION and package.json
 * must agree, and the version must be SemVer.
 */
function version() {
	const source = readFileSync( join( ROOT, 'merchboard.php' ), 'utf8' );
	const header = source.match( /^\s*\*\s*Version:\s*(\S+)\s*$/m )?.[ 1 ];
	const constant = source.match(
		/define\(\s*'MERCHBOARD_VERSION',\s*'([^']+)'\s*\)/
	)?.[ 1 ];
	const npm = JSON.parse(
		readFileSync( join( ROOT, 'package.json' ), 'utf8' )
	).version;

	if ( ! header || header !== constant || header !== npm ) {
		fail(
			`plugin header (${ header }), MERCHBOARD_VERSION (${ constant }) and package.json (${ npm }) must have the same version.`
		);
	}

	if ( ! SEMVER.test( header ) ) {
		fail( `version ${ header } is not SemVer (MAJOR.MINOR.PATCH).` );
	}

	return header;
}

/**
 * The release tag from `--tag <tag>`, or null for a local build.
 * @param {string[]} args Command line arguments.
 */
function releaseTag( args ) {
	const index = args.indexOf( '--tag' );

	if ( index === -1 ) {
		return null;
	}

	const tag = args[ index + 1 ];

	if ( ! tag ) {
		fail( '--tag needs a value, e.g. --tag v1.2.3.' );
	}

	return tag;
}

/**
 * A release tag must be `v<version>` and point at the commit being packaged.
 * @param {string} tag           Release tag.
 * @param {string} pluginVersion Plugin version.
 */
function assertTag( tag, pluginVersion ) {
	if ( tag !== `v${ pluginVersion }` ) {
		fail(
			`tag ${ tag } does not match the plugin version (expected v${ pluginVersion }).`
		);
	}

	let tagged;

	try {
		tagged = execFileSync(
			'git',
			[
				'rev-parse',
				'--verify',
				'--quiet',
				`refs/tags/${ tag }^{commit}`,
			],
			{
				cwd: ROOT,
				encoding: 'utf8',
				stdio: [ 'ignore', 'pipe', 'ignore' ],
			}
		).trim();
	} catch {
		fail( `tag ${ tag } does not exist.` );
	}

	if ( tagged !== git( 'rev-parse', 'HEAD' ) ) {
		fail( `tag ${ tag } does not point at HEAD.` );
	}
}

/**
 * Tracked runtime files must be exactly as committed at HEAD, and no
 * untracked files may hide in the runtime directories.
 */
function assertCleanTree() {
	const changed = git(
		'status',
		'--porcelain',
		'--untracked-files=all',
		'--',
		...TRACKED
	);

	if ( changed !== '' ) {
		fail(
			`runtime files differ from HEAD (commit or discard first):\n${ changed }`
		);
	}
}

function listDir( dir ) {
	const out = [];

	for ( const name of readdirSync( join( ROOT, dir ) ) ) {
		const path = `${ dir }/${ name }`;
		out.push(
			...( statSync( join( ROOT, path ) ).isDirectory()
				? listDir( path )
				: [ path ] )
		);
	}

	return out;
}

function packageFiles() {
	const tracked = git( 'ls-files', '--', ...TRACKED )
		.split( '\n' )
		.filter( Boolean );

	if ( ! existsSync( join( ROOT, GENERATED ) ) ) {
		fail( 'build/ is missing; run `npm run package` (it builds first).' );
	}

	const files = [ ...tracked, ...listDir( GENERATED ) ].map( ( f ) =>
		f.replace( /\\/g, '/' )
	);
	const unique = [ ...new Set( files ) ].sort();

	for ( const file of REQUIRED ) {
		if ( ! unique.includes( file ) ) {
			fail( `required runtime file missing: ${ file }` );
		}
	}

	for ( const file of unique ) {
		const hit = FORBIDDEN.find( ( pattern ) => pattern.test( file ) );

		if ( hit ) {
			fail( `forbidden file in package: ${ file } (${ hit })` );
		}
	}

	return unique;
}

/**
 * DOS date/time of a UNIX timestamp (UTC), for reproducible entries.
 * @param {number} seconds UNIX timestamp.
 */
function dosTime( seconds ) {
	const d = new Date( seconds * 1000 );
	const time =
		( d.getUTCHours() << 11 ) |
		( d.getUTCMinutes() << 5 ) |
		Math.floor( d.getUTCSeconds() / 2 );
	const date =
		( ( d.getUTCFullYear() - 1980 ) << 9 ) |
		( ( d.getUTCMonth() + 1 ) << 5 ) |
		d.getUTCDate();

	return { time, date };
}

/**
 * A ZIP (PKWARE APPNOTE, no ZIP64) with directory entries, sorted paths,
 * fixed timestamps and Unix permissions (0755 dirs, 0644 files).
 * @param {Array<{name: string, data: Buffer|null}>} entries   Sorted entries (null data = directory).
 * @param {number}                                   timestamp UNIX timestamp for every entry.
 */
function zip( entries, timestamp ) {
	const { time, date } = dosTime( timestamp );
	const locals = [];
	const centrals = [];
	let offset = 0;

	for ( const { name, data } of entries ) {
		const isDir = data === null;
		const nameBuf = Buffer.from( name, 'utf8' );
		const raw = isDir ? Buffer.alloc( 0 ) : data;
		const compressed = isDir ? raw : deflateRawSync( raw, { level: 9 } );
		const method = isDir ? 0 : 8;
		const crc = isDir ? 0 : crc32( raw );
		const mode = isDir ? 0o40755 : 0o100644;

		const local = Buffer.alloc( 30 );
		local.writeUInt32LE( 0x04034b50, 0 );
		local.writeUInt16LE( 20, 4 );
		local.writeUInt16LE( 0x0800, 6 ); // UTF-8 names.
		local.writeUInt16LE( method, 8 );
		local.writeUInt16LE( time, 10 );
		local.writeUInt16LE( date, 12 );
		local.writeUInt32LE( crc, 14 );
		local.writeUInt32LE( compressed.length, 18 );
		local.writeUInt32LE( raw.length, 22 );
		local.writeUInt16LE( nameBuf.length, 26 );
		local.writeUInt16LE( 0, 28 );
		locals.push( local, nameBuf, compressed );

		const central = Buffer.alloc( 46 );
		central.writeUInt32LE( 0x02014b50, 0 );
		central.writeUInt16LE( ( 3 << 8 ) | 20, 4 ); // Made by Unix, 2.0.
		central.writeUInt16LE( 20, 6 );
		central.writeUInt16LE( 0x0800, 8 );
		central.writeUInt16LE( method, 10 );
		central.writeUInt16LE( time, 12 );
		central.writeUInt16LE( date, 14 );
		central.writeUInt32LE( crc, 16 );
		central.writeUInt32LE( compressed.length, 20 );
		central.writeUInt32LE( raw.length, 24 );
		central.writeUInt16LE( nameBuf.length, 28 );
		central.writeUInt32LE(
			( ( mode << 16 ) | ( isDir ? 0x10 : 0 ) ) >>> 0,
			38
		);
		central.writeUInt32LE( offset, 42 );
		centrals.push( central, nameBuf );

		offset += local.length + nameBuf.length + compressed.length;
	}

	const directory = Buffer.concat( centrals );
	const end = Buffer.alloc( 22 );
	end.writeUInt32LE( 0x06054b50, 0 );
	end.writeUInt16LE( entries.length, 8 );
	end.writeUInt16LE( entries.length, 10 );
	end.writeUInt32LE( directory.length, 12 );
	end.writeUInt32LE( offset, 16 );

	return Buffer.concat( [ ...locals, directory, end ] );
}

/**
 * Reads a ZIP back: name → content (null for directories), verifying CRCs.
 * @param {Buffer} buffer ZIP file.
 */
function unzip( buffer ) {
	const endOffset = buffer.lastIndexOf(
		Buffer.from( [ 0x50, 0x4b, 0x05, 0x06 ] )
	);
	const count = buffer.readUInt16LE( endOffset + 10 );
	let pointer = buffer.readUInt32LE( endOffset + 16 );
	const entries = new Map();

	for ( let i = 0; i < count; i++ ) {
		const method = buffer.readUInt16LE( pointer + 10 );
		const crc = buffer.readUInt32LE( pointer + 16 );
		const size = buffer.readUInt32LE( pointer + 20 );
		const nameLength = buffer.readUInt16LE( pointer + 28 );
		const extra = buffer.readUInt16LE( pointer + 30 );
		const comment = buffer.readUInt16LE( pointer + 32 );
		const localOffset = buffer.readUInt32LE( pointer + 42 );
		const name = buffer.toString(
			'utf8',
			pointer + 46,
			pointer + 46 + nameLength
		);
		const dataStart =
			localOffset +
			30 +
			buffer.readUInt16LE( localOffset + 26 ) +
			buffer.readUInt16LE( localOffset + 28 );
		const stored = buffer.subarray( dataStart, dataStart + size );
		let data = null;

		if ( ! name.endsWith( '/' ) ) {
			data = method === 8 ? inflateRawSync( stored ) : stored;
		}

		if ( data !== null && crc32( data ) !== crc ) {
			fail( `CRC mismatch in the written ZIP: ${ name }` );
		}

		entries.set( name, data );
		pointer += 46 + nameLength + extra + comment;
	}

	return entries;
}

function main() {
	const pluginVersion = version();
	const tag = releaseTag( process.argv.slice( 2 ) );

	if ( tag !== null ) {
		assertTag( tag, pluginVersion );
	}

	assertCleanTree();

	const files = packageFiles();
	const head = git( 'rev-parse', '--short', 'HEAD' );
	const timestamp = Number( git( 'log', '-1', '--format=%ct' ) );

	const dirs = new Set( [ `${ PLUGIN_DIR }/` ] );
	for ( const file of files ) {
		const parts = file.split( '/' );
		for ( let i = 1; i < parts.length; i++ ) {
			dirs.add( `${ PLUGIN_DIR }/${ parts.slice( 0, i ).join( '/' ) }/` );
		}
	}

	const entries = [
		...[ ...dirs ].map( ( name ) => ( { name, data: null } ) ),
		...files.map( ( file ) => ( {
			name: `${ PLUGIN_DIR }/${ file }`,
			data: readFileSync( join( ROOT, file ) ),
		} ) ),
	].sort( ( a, b ) => ( a.name < b.name ? -1 : 1 ) );

	const archive = zip( entries, timestamp );
	const outDir = join( ROOT, 'dist' );
	const outFile = join( outDir, `merchboard-mvp-${ pluginVersion }.zip` );
	mkdirSync( outDir, { recursive: true } );
	writeFileSync( outFile, archive );

	// Validate by reading the file back.
	const read = unzip( readFileSync( outFile ) );
	const names = [ ...read.keys() ];

	if ( names.some( ( n ) => ! n.startsWith( `${ PLUGIN_DIR }/` ) ) ) {
		fail( 'every entry must be inside merchboard/.' );
	}

	for ( const { name, data } of entries ) {
		if (
			! read.has( name ) ||
			( data !== null && ! read.get( name ).equals( data ) )
		) {
			fail( `entry differs after writing: ${ name }` );
		}
	}

	const mainFile = read
		.get( `${ PLUGIN_DIR }/merchboard.php` )
		.toString( 'utf8' );
	if (
		! mainFile.includes( `Version:           ${ pluginVersion }` ) ||
		! mainFile.includes( 'Plugin Name:' )
	) {
		fail( 'merchboard.php in the ZIP has no valid plugin header.' );
	}

	const fileCount = names.filter( ( n ) => ! n.endsWith( '/' ) ).length;
	const sha256 = createHash( 'sha256' ).update( archive ).digest( 'hex' );
	const topLevel = [
		...new Set( files.map( ( f ) => f.split( '/' )[ 0 ] ) ),
	].sort();

	console.log(
		`package: ${ relative( ROOT, outFile ).replace( /\\/g, '/' ) }`
	);
	console.log(
		`  version:   ${ pluginVersion } (HEAD ${ head }${
			tag === null ? '' : `, tag ${ tag }`
		})`
	);
	console.log( `  root:      ${ PLUGIN_DIR }/` );
	console.log( `  contents:  ${ topLevel.join( ', ' ) }` );
	console.log(
		`  files:     ${ fileCount } (+ ${ names.length - fileCount } directories)`
	);
	console.log( `  size:      ${ archive.length } bytes` );
	console.log( `  sha256:    ${ sha256 }` );
}

main();
